/**
 * Content blocks represent displayable information in the Agent Client Protocol.
 *
 * They provide a structured way to handle various types of user-facing content—whether
 * it's text from language models, images for analysis, or embedded resources for context.
 *
 * Content blocks appear in:
 * - User prompts sent via `session/prompt`
 * - Language model output reported through `session/update` notifications as
 *   message updates or streamed chunks
 * - Progress updates and results from tool calls
 *
 * This structure is compatible with the Model Context Protocol (MCP), enabling
 * agents to seamlessly forward content from MCP tool outputs without transformation.
 *
 * See protocol docs: [Content](https://agentclientprotocol.com/protocol/v2/content)
 */
export type ContentBlock = (({
  readonly type: "text"
}) & (TextContent)) | (({
  readonly type: "image"
}) & (ImageContent)) | (({
  readonly type: "audio"
}) & (AudioContent)) | (({
  readonly type: "resource_link"
}) & (ResourceLink)) | (({
  readonly type: "resource"
}) & (EmbeddedResource)) | ({
  /**
   * Custom or future content block type.
   *
   * Values beginning with `_` are reserved for implementation-specific
   * extensions. Unknown values that do not begin with `_` are reserved for
   * future ACP variants.
   */
  readonly type: string
})
export const ContentBlock = Wire.refinedDef<ContentBlock>("ContentBlock", Schema.Union([
  Wire.allOf(
    Wire.object({
      type: Schema.Literal("text")
    }),
    TextContent
  ),
  Wire.allOf(
    Wire.object({
      type: Schema.Literal("image")
    }),
    ImageContent
  ),
  Wire.allOf(
    Wire.object({
      type: Schema.Literal("audio")
    }),
    AudioContent
  ),
  Wire.allOf(
    Wire.object({
      type: Schema.Literal("resource_link")
    }),
    ResourceLink
  ),
  Wire.allOf(
    Wire.object({
      type: Schema.Literal("resource")
    }),
    EmbeddedResource
  ),
  Wire.not(
    Wire.object({
      type: Schema.String
    }),
    Schema.Union([
      Wire.object({
        type: Schema.Literal("text")
      }),
      Wire.object({
        type: Schema.Literal("image")
      }),
      Wire.object({
        type: Schema.Literal("audio")
      }),
      Wire.object({
        type: Schema.Literal("resource_link")
      }),
      Wire.object({
        type: Schema.Literal("resource")
      })
    ])
  )
]))

